import kotlin.math.ceil

fun main() {
    val n = readLine()!!.toInt()
    val a = readLine()!!.split(" ").map { it.toInt() }.toIntArray()
    val b = readLine()!!.split(" ").map { it.toInt() }.toIntArray()

    var rez = 0
    for (i in 0 until n) {
        if (a[i] == 1 && b[i] == 0) rez++
    }
    val aSum = a.sum()
    val bSum = b.sum()

    if (aSum > bSum) {
        println(1)
    } else if (rez == 0 || aSum == 0 || (aSum == n && bSum == n)) {
        println(-1)
    } else {
        val diff = bSum - aSum + 1
        val div = diff / rez.toDouble()
        val result = ceil(div).toInt() + 1
        println(result)
    }
}

